using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class AsyncStatsComponent : GH_Component
    {
        private CancellationTokenSource _cts;
        private bool _ready;
        private double _mean;
        private double _stdDev;

        public AsyncStatsComponent()
            : base("Async Stats", "AStats", "Computes mean and standard deviation asynchronously", "Bench", "Data")
        {
        }

        public override Guid ComponentGuid => new Guid("b1d2e3f4-5555-4a2b-9c3d-0a1b2c3d4e55");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Values", "V", "List of numbers", GH_ParamAccess.list);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Mean", "M", "Arithmetic mean", GH_ParamAccess.item);
            pManager.AddNumberParameter("StdDev", "S", "Population standard deviation", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            // Second pass, triggered by the finished background task.
            if (_ready)
            {
                _ready = false;
                DA.SetData(0, _mean);
                DA.SetData(1, _stdDev);
                return;
            }

            var values = new List<double>();
            if (!DA.GetDataList(0, values)) return;

            // Inputs changed: cancel the previous computation.
            _cts?.Cancel();
            _cts?.Dispose();
            var cts = new CancellationTokenSource();
            _cts = cts;
            var token = cts.Token;

            Task.Run(() =>
            {
                double mean = 0, std = 0;
                if (values.Count > 0)
                {
                    mean = values.Average();
                    double sum = 0;
                    foreach (var v in values)
                    {
                        token.ThrowIfCancellationRequested();
                        sum += (v - mean) * (v - mean);
                    }
                    std = Math.Sqrt(sum / values.Count);
                }
                token.ThrowIfCancellationRequested();
                return (mean, std);
            }, token).ContinueWith(t =>
            {
                if (t.Status != TaskStatus.RanToCompletion || token.IsCancellationRequested) return;
                _mean = t.Result.mean;
                _stdDev = t.Result.std;
                _ready = true;
                Rhino.RhinoApp.InvokeOnUiThread((Action)(() => ExpireSolution(true)));
            }, TaskScheduler.Default);
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            _cts?.Cancel();
            base.RemovedFromDocument(document);
        }
    }
}
